import type { CameraRig, Shot } from "./camera-rig";

export interface CameraTunerOptions {
  rig: CameraRig;
  /** Only so the panel can print each fraction in world units beside it. */
  worldSize: number;
  maxHeight: number;
  /**
   * Trail's own setProgress. The scrub drives it alongside the camera,
   * because framing is being judged against the drawn line and the flag -
   * a preview that moves the camera to the summit and leaves the mountain
   * bare shows the one thing the shot does not have to hold.
   */
  setTrailProgress?: (t: number) => void;
}

interface Knob {
  key: keyof Shot;
  label: string;
  min: number;
  max: number;
  step: number;
  /** Turns the stored fraction into the world-unit reading shown beside it. */
  unit?: (value: number, o: CameraTunerOptions) => string;
}

const KNOBS: Knob[] = [
  { key: "distance", label: "zoom (distance)", min: 0.2, max: 1.4, step: 0.01, unit: (v, o) => `${Math.round(v * o.worldSize)}u out` },
  { key: "height", label: "height", min: 0, max: 1.6, step: 0.01, unit: (v, o) => `${Math.round(v * o.maxHeight)}u up` },
  { key: "pitch", label: "vertical angle", min: -40, max: 40, step: 0.1, unit: (v) => (v >= 0 ? `${v.toFixed(1)}° up` : `${(-v).toFixed(1)}° down`) },
  { key: "fov", label: "lens (fov)", min: 12, max: 80, step: 0.5, unit: (v) => `${v.toFixed(1)}°` },
];

/**
 * Dev-only framing panel, opened with ?camera.
 *
 * The two shots in camera-rig.ts are meant to be tuned by eye against the
 * real render - every value in them was - and doing that by editing a
 * constant, waiting for a reload and scrolling back to the part of the climb
 * you were judging is slow enough that it changes what you are willing to
 * try. This writes to rig.shots directly, so a slider moves the camera on
 * the next frame, and prints the block to paste back into the module once
 * the framing is right. Nothing here is loaded unless ?camera is in the URL.
 */
export function createCameraTuner(options: CameraTunerOptions): () => void {
  const { rig } = options;

  const panel = document.createElement("div");
  Object.assign(panel.style, {
    position: "fixed",
    top: "12px",
    right: "12px",
    zIndex: "2147483647",
    width: "268px",
    padding: "12px 14px",
    borderRadius: "8px",
    background: "rgba(14, 20, 32, 0.9)",
    color: "#eef3fb",
    font: "11px/1.5 ui-monospace, SFMono-Regular, Menlo, monospace",
    // The canvas sits behind everything with pointer-events off; this panel
    // is the one thing in front of it that has to take a drag.
    pointerEvents: "auto",
    backdropFilter: "blur(6px)",
    maxHeight: "calc(100vh - 24px)",
    overflowY: "auto",
  });

  const heading = document.createElement("div");
  heading.textContent = "camera framing";
  Object.assign(heading.style, { fontWeight: "700", letterSpacing: "0.08em", textTransform: "uppercase", marginBottom: "10px", opacity: "0.7" });
  panel.appendChild(heading);

  const output = document.createElement("pre");
  Object.assign(output.style, {
    margin: "10px 0 0",
    padding: "8px",
    borderRadius: "6px",
    background: "rgba(0,0,0,0.35)",
    whiteSpace: "pre-wrap",
    fontSize: "10px",
    lineHeight: "1.45",
  });

  const render = () => {
    const line = (name: string, shot: Shot) =>
      `const ${name}: Shot = { distance: ${+shot.distance.toFixed(3)}, height: ${+shot.height.toFixed(3)}, pitch: ${+shot.pitch.toFixed(1)}, fov: ${+shot.fov.toFixed(1)} };`;
    output.textContent = `${line("BASE_SHOT", rig.shots.base)}\n${line("SUMMIT_SHOT", rig.shots.summit)}`;
  };

  const addSlider = (shot: Shot, knob: Knob) => {
    const row = document.createElement("label");
    Object.assign(row.style, { display: "block", margin: "0 0 8px" });

    const caption = document.createElement("span");
    Object.assign(caption.style, { display: "flex", justifyContent: "space-between", gap: "8px", opacity: "0.85" });
    const name = document.createElement("span");
    name.textContent = knob.label;
    const value = document.createElement("span");
    caption.append(name, value);

    const input = document.createElement("input");
    input.type = "range";
    input.min = String(knob.min);
    input.max = String(knob.max);
    input.step = String(knob.step);
    input.value = String(shot[knob.key]);
    Object.assign(input.style, { width: "100%", margin: "2px 0 0", accentColor: "#c9b795" });

    const sync = () => {
      value.textContent = knob.unit ? knob.unit(shot[knob.key], options) : String(shot[knob.key]);
    };
    input.addEventListener("input", () => {
      shot[knob.key] = Number(input.value);
      sync();
      render();
    });
    sync();

    row.append(caption, input);
    panel.appendChild(row);
  };

  for (const [name, shot] of [["base (scroll 0)", rig.shots.base], ["summit (scroll 1)", rig.shots.summit]] as const) {
    const group = document.createElement("div");
    group.textContent = name;
    Object.assign(group.style, { margin: "10px 0 6px", opacity: "0.55", letterSpacing: "0.06em" });
    panel.appendChild(group);
    for (const knob of KNOBS) addSlider(shot as Shot, knob);
  }

  // Scrubbing the climb from here rather than from the page: judging the
  // summit end of the crane otherwise means scrolling to the bottom after
  // every single change.
  const scrubLabel = document.createElement("div");
  scrubLabel.textContent = "preview progress";
  Object.assign(scrubLabel.style, { margin: "12px 0 2px", opacity: "0.55", letterSpacing: "0.06em" });
  const scrub = document.createElement("input");
  scrub.type = "range";
  scrub.min = "0";
  scrub.max = "1";
  scrub.step = "0.005";
  scrub.value = String(rig.currentProgress());
  Object.assign(scrub.style, { width: "100%", accentColor: "#c9b795" });
  // jumpTo, not setProgress: a scrub is a position, not a scroll, and the
  // rig damping would turn every nudge into a slow drift toward it. Scroll
  // takes the camera back off this the moment the page moves.
  scrub.addEventListener("input", () => {
    const t = Number(scrub.value);
    rig.jumpTo(t);
    options.setTrailProgress?.(t);
  });
  panel.append(scrubLabel, scrub);

  const hint = document.createElement("div");
  hint.textContent = "paste into src/scene/camera-rig.ts";
  Object.assign(hint.style, { margin: "12px 0 0", opacity: "0.55" });
  panel.append(hint, output);

  render();
  document.body.appendChild(panel);

  return () => panel.remove();
}
